:root {
  --color-bg: #2b2d42;
  --color-card: #edf2f4;
  --color-primary: #ef233c;
  --color-secondary: #8d99ae;
  --color-text: #2b2d42;
  --color-accent: #d90429;
  --font-size-base: 18px;
  --spacing: 1.5rem;
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background-color: var(--color-bg);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: var(--font-size-base);
  color: var(--color-text);
  padding: 1rem;
}

.game-card {
  background-color: var(--color-card);
  border-radius: var(--border-radius);
  padding: var(--spacing);
  max-width: 600px;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.2rem;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.8rem;
  color: var(--color-text);
  text-align: center;
}

canvas {
  background-color: #fff;
  border-radius: 8px;
  width: 200px;
  height: 200px;
  image-rendering: pixelated;
}

.word-display {
  font-size: 2rem;
  letter-spacing: 0.5rem;
  text-align: center;
  font-weight: bold;
  color: var(--color-text);
  min-height: 2.5rem;
}

.status {
  font-size: 1.2rem;
  text-align: center;
  min-height: 1.5rem;
  color: var(--color-accent);
}

.letter-buttons {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.5rem;
  max-width: 100%;
}

.letter-buttons button {
  width: 2.5rem;
  height: 2.5rem;
  font-size: 1.2rem;
  font-weight: bold;
  border: 2px solid var(--color-secondary);
  border-radius: 6px;
  background-color: #fff;
  color: var(--color-text);
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.letter-buttons button:hover:not(:disabled) {
  background-color: var(--color-secondary);
  color: #fff;
}

.letter-buttons button:focus-visible {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.letter-buttons button:active:not(:disabled) {
  transform: scale(0.95);
}

.letter-buttons button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background-color: #eee;
}

.new-game-btn {
  padding: 0.8rem 2rem;
  font-size: 1.2rem;
  font-weight: bold;
  background-color: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.new-game-btn:hover {
  background-color: var(--color-accent);
}

.new-game-btn:focus-visible {
  outline: 3px solid var(--color-text);
  outline-offset: 2px;
}

.new-game-btn:active {
  transform: scale(0.95);
}

@media (max-width: 400px) {
  :root {
    --spacing: 1rem;
  }
  .game-card {
    padding: 1rem;
  }
  .word-display {
    font-size: 1.5rem;
    letter-spacing: 0.3rem;
  }
  .letter-buttons button {
    width: 2rem;
    height: 2rem;
    font-size: 1rem;
  }
}

const words = [
  'JAVASCRIPT', 'PYTHON', 'HTML', 'CSS', 'REACT', 'ANGULAR', 'VUE', 'NODE', 'EXPRESS', 'MONGODB',
  'SQL', 'GIT', 'DOCKER', 'KUBERNETES', 'LINUX', 'WINDOWS', 'MACOS', 'ANDROID', 'IOS', 'RUST',
  'GO', 'SWIFT', 'KOTLIN', 'TYPESCRIPT', 'RUBY', 'PHP', 'JAVA', 'C', 'CPP', 'CSHARP'
];

const canvas = document.getElementById('hangman-canvas');
const ctx = canvas.getContext('2d');
const wordDisplay = document.getElementById('word-display');
const statusMessage = document.getElementById('status-message');
const letterButtonsContainer = document.getElementById('letter-buttons');
const newGameBtn = document.getElementById('new-game-btn');

let currentWord = '';
let guessedLetters = new Set();
let wrongGuesses = 0;
const maxWrong = 6;
let gameActive = true;

function initGame() {
  currentWord = words[Math.floor(Math.random() * words.length)];
  guessedLetters.clear();
  wrongGuesses = 0;
  gameActive = true;
  statusMessage.textContent = 'Guess a letter';
  renderWord();
  drawHangman();
  createLetterButtons();
}

function renderWord() {
  wordDisplay.textContent = currentWord
    .split('')
    .map(letter => (guessedLetters.has(letter) ? letter : '_'))
    .join(' ');
}

function createLetterButtons() {
  letterButtonsContainer.innerHTML = '';
  for (let i = 65; i <= 90; i++) {
    const letter = String.fromCharCode(i);
    const btn = document.createElement('button');
    btn.textContent = letter;
    btn.setAttribute('aria-label', `Letter ${letter}`);
    btn.addEventListener('click', () => handleGuess(letter));
    if (guessedLetters.has(letter)) {
      btn.disabled = true;
    }
    letterButtonsContainer.appendChild(btn);
  }
}

function handleGuess(letter) {
  if (!gameActive || guessedLetters.has(letter)) return;
  guessedLetters.add(letter);
  const btn = Array.from(letterButtonsContainer.children).find(b => b.textContent === letter);
  if (btn) btn.disabled = true;

  if (currentWord.includes(letter)) {
    renderWord();
    if (currentWord.split('').every(l => guessedLetters.has(l))) {
      gameActive = false;
      statusMessage.textContent = 'You win! 🎉';
      disableAllButtons();
    }
  } else {
    wrongGuesses++;
    drawHangman();
    if (wrongGuesses >= maxWrong) {
      gameActive = false;
      statusMessage.textContent = `You lose! The word was ${currentWord}`;
      disableAllButtons();
      wordDisplay.textContent = currentWord.split('').join(' ');
    }
  }
}

function disableAllButtons() {
  Array.from(letterButtonsContainer.children).forEach(btn => btn.disabled = true);
}

function drawHangman() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  const pixel = 10;
  ctx.fillStyle = '#2b2d42';

  // Gallows base
  ctx.fillRect(40, 180, 120, 10);
  ctx.fillRect(80, 40, 10, 140);
  ctx.fillRect(80, 40, 80, 10);
  ctx.fillRect(150, 40, 10, 20);

  // Head
  if (wrongGuesses >= 1) {
    ctx.beginPath();
    ctx.arc(155, 70, 15, 0, Math.PI * 2);
    ctx.fill();
  }
  // Body
  if (wrongGuesses >= 2) {
    ctx.fillRect(150, 85, 10, 50);
  }
  // Left arm
  if (wrongGuesses >= 3) {
    ctx.fillRect(130, 90, 20, 10);
  }
  // Right arm
  if (wrongGuesses >= 4) {
    ctx.fillRect(160, 90, 20, 10);
  }
  // Left leg
  if (wrongGuesses >= 5) {
    ctx.fillRect(135, 135, 15, 10);
  }
  // Right leg
  if (wrongGuesses >= 6) {
    ctx.fillRect(160, 135, 15, 10);
  }
}

newGameBtn.addEventListener('click', initGame);

initGame();
